/// <summary> Конструктор класса </summary>
public void new()
{
    super();

    apiClient = new RMarketApiClientBybit();
    apiClient.parmHttpMethod(RMarketAPIHttpMethod::POST);
    apiClient.parmMethodUrl('/v5/account/set-collateral-switch');

    requestContract = new RMarketJson_Bybit_SetCollateral_Request();

    // Do this before execute()
    //apiClient.setBaseUrl(URL _baseUrl);
    //apiClient.setApiKey(RMarketApiKey _apiKey)
}

/// <summary> Отменить ордер на Bybit </summary>
/// <param name="_symbol"> Торговый символ </param>
/// <param name="_orderId"> ID ордера </param>
/// <returns> Результат удаления ордера </returns>
public void initParameters(
    str _coin,
    boolean _collateralSwitch)
{
    //https://bybit-exchange.github.io/docs/v5/order/cancel-order
    //category	true	string	Product type
    //                            UTA2.0, UTA1.0: linear, inverse, spot, option
    //                            classic account: linear, inverse, spot
    //symbol	    true	string	Symbol name, like BTCUSDT, uppercase only
    //orderId	    false	string	Order ID. Either orderId or orderLinkId is required
    //orderLinkId	false	string	User customised order ID. Either orderId or orderLinkId is required
    //orderFilter	false	string	Spot trading only
    //                            Order
    //                            tpslOrder
    //                            StopOrder
    //                            If not passed, Order by default
    coin = _coin;
    collateralSwitch = _collateralSwitch ? "ON" : "OFF";

    requestContract.parmCoin(coin);
    requestContract.parmCollateralSwitch(collateralSwitch);
}

public void processResponse()
{
    super();

    str responseStr = apiClient.getResponseBody();

    if (apiClient.getHttpStatus() != System.Net.HttpStatusCode::OK)
        throw Error(strfmt("Request returns error!"));

    responseContract = RMarketJsonSerializer::deserializeObject(
        classNum(RMarketJson_Bybit_Response),
        responseStr) as RMarketJson_Bybit_Response;
}
